using System;
using UnityEngine;

namespace TribalTrouble.Presentation
{
    /// <summary>
    /// One entry of the original geometry.xml ("sprite"): a model with LODs, texture
    /// variants (e.g. rock / iron / rubber warriors) and skeletal animations.
    /// Generated by Tools &gt; Tribal Trouble &gt; Build Sprite Catalog from catalog.json.
    /// </summary>
    [CreateAssetMenu(menuName = "Tribal Trouble/Sprite Definition")]
    public sealed class TTSpriteDefinition : ScriptableObject
    {
        public string group;
        public string spriteName;
        [Tooltip("Imported .glb (geometry, skin and animation clips).")]
        public GameObject model;
        public bool skinned;
        public LodInfo[] lods = Array.Empty<LodInfo>();
        public AnimInfo[] animations = Array.Empty<AnimInfo>();

        public string Key => group + "/" + spriteName;

        public int FindAnimation(string animationName)
        {
            for (int i = 0; i < animations.Length; i++)
                if (string.Equals(animations[i].name, animationName, StringComparison.OrdinalIgnoreCase))
                    return i;
            return -1;
        }

        [Serializable]
        public sealed class LodInfo
        {
            [Tooltip("Name of the child GameObject holding this LOD's renderer (lod0, lod1, ...).")]
            public string nodeName;
            public TextureVariant[] textures = Array.Empty<TextureVariant>();
            [Tooltip("Original 'clear colour' used by TT for impostor rendering.")]
            public Color clearColor = Color.black;
            public bool alphaClip;
        }

        [Serializable]
        public sealed class TextureVariant
        {
            public string name;
            public Texture2D baseMap;
            public Texture2D teamMask;
        }

        [Serializable]
        public sealed class AnimInfo
        {
            public string name;
            public AnimationClip clip;
            [Tooltip("World units per cycle: TT advances clip cycles by anim_ticks / wpc.")]
            public float wpc = 1f;
            public bool loop = true;
            public int frames;
        }
    }
}
